<section style={{ ...page.carte, padding: 16, marginBottom: 20 }}>
  <h2 style={{ margin: "0 0 4px", fontSize: 20 }}>Répartition du temps, par activité</h2>
  <p style={{ margin: "0 0 12px", color: C.gris, fontSize: 14 }}>
